/**
 * The sprite sheet guard.
 *
 * The sprites are generated by scripts/generate_koban_sprites.py. This
 * checks the things that are easy to break without noticing: that the
 * generator still draws the same files, that the strips are
 * transparent, and that the CSS steps through whole frames.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
// HERE is frontend/src/features/koban-shop/__tests__ - four levels up
// is the frontend directory.
const FRONT = path.join(HERE, '..', '..', '..', '..');
const ROOT = path.join(FRONT, '..');
const read = (rel) => fs.readFileSync(path.join(FRONT, rel), 'utf8');

let passed = 0;
let failed = 0;
const must = (cond, msg) => {
  if (cond) {
    passed += 1;
    console.log(`ok - ${msg}`);
  } else {
    failed += 1;
    console.log(`not ok - ${msg}`);
  }
};

const CHARS = ['koneko', 'minori', 'kaneru', 'kogane', 'mone', 'zenimaru'];
const ANIMS = { idle: 3, walk: 4, celebrate: 3, work: 2 };

// ---------------------------------------------------------------------------
// The generator
// ---------------------------------------------------------------------------

const generator = fs.readFileSync(path.join(ROOT, 'scripts', 'generate_koban_sprites.py'), 'utf8');

must(generator.includes('def main'), 'the generator has an entry point');
must(generator.includes('--check'), 'the generator can check its own output');
must(generator.includes('SEED') || !/random\./.test(generator), 'the generator is deterministic - no unseeded random');

// The frame maths. A sheet is 4 rows of 3 columns, and the walk row
// uses four frames, so the sheet is four columns wide for that row.
must(/COLS, ROWS = 3, 4/.test(generator), 'the sheet is 3 columns by 4 rows');
must(/ROW_FRAMES = \{ROW_IDLE: 3, ROW_WALK: 4, ROW_CELEBRATE: 3, ROW_WORK: 2\}/.test(generator),
  'the rows have the frame counts the brief asks for');

// Every character needs a palette and a signature, or the renderer
// would fall over on the first frame.
must(/PALETTES = \{/.test(generator), 'the generator holds a palette per character');
for (const c of CHARS) {
  must(generator.includes(`"${c}": {`), `${c} has a palette`);
}
must(/SIGNATURES = \{/.test(generator), 'every character has a signature accessory and a prop');

// ---------------------------------------------------------------------------
// The files
// ---------------------------------------------------------------------------

const spriteDir = path.join(FRONT, 'public', 'koban-assets', 'sprites');
for (const c of CHARS) {
  must(fs.existsSync(path.join(spriteDir, `${c}.png`)), `${c}.png (the sheet) exists`);
  must(fs.existsSync(path.join(spriteDir, `${c}_portrait.png`)), `${c}_portrait.png exists`);
  for (const [anim, frames] of Object.entries(ANIMS)) {
    const p = path.join(spriteDir, `${c}_${anim}.png`);
    must(fs.existsSync(p), `${c}_${anim}.png exists`);
    // The PNG header carries the size in bytes 16..24.
    if (fs.existsSync(p)) {
      const buf = fs.readFileSync(p);
      const width = buf.readUInt32BE(16);
      const height = buf.readUInt32BE(20);
      must(width === 48 * frames && height === 64,
        `${c}_${anim}.png is ${frames} frames of 48x64 (got ${width}x${height})`);
    }
  }
}

// ---------------------------------------------------------------------------
// The CSS
// ---------------------------------------------------------------------------

const css = read('src/features/koban-shop/koban.css');

must(css.includes('image-rendering: pixelated'), 'the sprites are drawn with hard pixels');
must(css.includes('steps(3)'), 'the idle and celebration loops step through three frames');
must(css.includes('steps(4)'), 'the walk loop steps through four frames');
must(css.includes('steps(2)'), 'the work loop steps through two frames');

// The percentage. A background-position percentage is measured against
// (container - image), so one frame is 1/(N-1) of the overflow and
// the keyframe range has to be N/(N-1). Getting this wrong shows the
// whole strip at once.
must(/koban-sprite-idle[\s\S]{0,200}150%/.test(css), 'the idle loop shifts by 150% - one frame of a three-frame strip');
must(/koban-sprite-walk[\s\S]{0,200}133\.3333%/.test(css), 'the walk loop shifts by 133.3333% - one frame of a four-frame strip');
must(/koban-sprite-work[\s\S]{0,200}200%/.test(css), 'the work loop shifts by 200% - one frame of a two-frame strip');

// The reduced-motion guard has to stop the sprite steps too.
const reduced = css.slice(css.indexOf('prefers-reduced-motion'));
must(reduced.includes('.koban-sprite__strip'), 'reduced motion stops the sprite animation');

// ---------------------------------------------------------------------------
// The wiring
// ---------------------------------------------------------------------------

const stage = read('src/features/koban-shop/components/IsometricAtelierStage.jsx');
must(stage.includes('koban-sprite__strip'), 'the stage renders a sprite strip');
must(stage.includes('koban-sprite--standing'), 'the stage marks the companions as standing');
must(stage.includes('backgroundSize'), 'the strip is scaled to the frame count');
must(stage.includes('celebrate'), 'the stage has a celebration pose');

const dock = read('src/features/koban-shop/components/SkillCooldownDock.jsx');
must(dock.includes('_portrait.png'), 'the dock shows the generated portrait');

const page = read('src/features/koban-shop/KobanShopPage.jsx');
must(page.includes('celebratingId'), 'the page tracks who celebrated');

// ---------------------------------------------------------------------------
// The generated database
// ---------------------------------------------------------------------------

const db = JSON.parse(read('src/features/koban-shop/data/database.json'));
must(db.characters.length === 6, 'the database has six characters');
must(db.facilities.length === 4, 'the database has four facilities');
must(db.items.length >= 150, `the database has 150+ items (${db.items.length})`);
must(db.customerRequests.length === 12, 'the database has twelve requests');
must(db.dungeons.length === 5, 'the database has five dungeons');

// Every companion must stand inside the room, on the floor or behind
// the counter - not floating over the back wall.
for (const c of db.characters.filter((c) => c.stageCoords.scene === 'atelier')) {
  must(c.stageCoords.yPercent >= 45,
    `${c.id} stands in the room (y=${c.stageCoords.yPercent}%), not over the back wall`);
  must(c.stageCoords.xPercent >= 5 && c.stageCoords.xPercent <= 95,
    `${c.id} is inside the room (x=${c.stageCoords.xPercent}%)`);
}

const quests = JSON.parse(read('src/features/koban-shop/data/quests.json'));
must(quests.quests.length === 12, 'the quest file has twelve quests');
must(quests.meta.evaluation.perfect.multiplier === 1.5, 'a perfect answer pays 150%');
must(quests.meta.evaluation.acceptable.multiplier === 1.0, 'an acceptable answer pays 100%');
must(quests.meta.evaluation.wrong.multiplier === 0, 'a wrong answer pays nothing');
must(quests.meta.evaluation.wrong.keepsItem === true, 'a wrong answer does not cost the item');

console.log(`\nkoban sprites: ${passed} passed, ${failed} failed`);
if (failed) process.exit(1);
